const $ = id=>document.getElementById(id);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const round = n => Number.isFinite(n)?(Math.round(n*10)/10).toFixed(1):'—';
const whole = n => Number.isFinite(n)?String(Math.round(n)):'—';
const sum = a => a.reduce((n,x)=>n+(Number.isFinite(x)?x:0),0);
const formattedDay = d => new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',timeZone:'America/New_York'});
const shortDay = d => new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'America/New_York'});
const formattedTime = d => {try{return new Date(d).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/New_York',timeZoneName:'short'})}catch{return 'Unknown'}};
const yearNow = new Date().getFullYear();
const storage={get(k,age){try{const x=JSON.parse(localStorage.getItem('skinc-'+k));return x&&Date.now()-x.time<age?x.value:null}catch{return null}},set(k,v){try{localStorage.setItem('skinc-'+k,JSON.stringify({time:Date.now(),value:v}))}catch{}}};
async function requestJSON(url,timeout=23000){const c=new AbortController(),timer=setTimeout(()=>c.abort(),timeout);try{const r=await fetch(url,{signal:c.signal});if(!r.ok)throw Error('Service returned '+r.status);const d=await r.json();if(d.error)throw Error(d.error);return d}finally{clearTimeout(timer)}}

let state={forecast:null,byId:new Map(),reports:null,listings:null,period:3,filter:'all',history:null,historyPlace:'beech',historyStation:'auto',historyYear:yearNow,historyMode:'winter',observations:{},maps:[],loading:true};
function route(){let p=location.pathname.replace(/\/+$/,'')||'/';if(p==='/')return {kind:'home'};if(p==='/snowfall')return {kind:'snowfall'};if(p==='/mountains')return {kind:'mountains'};if(p==='/trail-maps')return {kind:'trail-maps'};if(p==='/methodology')return {kind:'methodology'};if(p.startsWith('/resorts/')){const resort=getResort(p.split('/')[2]);return resort?{kind:'resort',resort}:{kind:'not-found'}}return {kind:'not-found'}}
const currentRoute=route();
