function shell(inner){
 const path=location.pathname;const links=linkPaths.map(([href,label])=>`<a class="${path===href||path.replace(/\/$/,'')===href.replace(/\/$/,'')?'active':''}" href="${href}">${label}</a>`).join('');
 $('app').innerHTML=`<a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="container nav">${logo}<nav aria-label="Main" class="desktop-nav">${links}</nav><div class="nav-right"><span class="live-pill"><span id="status-dot" class="status-dot loading"></span><span id="feed-status">Checking models</span></span><a class="btn btn-primary btn-sm nav-cta" href="/snowfall/">Snowfall explorer ↗</a><button class="menu-button" id="menu-button" aria-label="Open navigation" aria-expanded="false">☰</button></div></div><nav aria-label="Mobile" id="mobile-nav" class="container mobile-nav">${links}<a href="/methodology/">Data sources</a></nav></header><main id="main">${inner}</main><footer class="footer"><div class="container footer-inner"><div>${logo}<p>North Carolina skiing. Right now. Forecast numbers are model estimates, station snowfall is measured at a specific observing site, and resort snowmaking is not natural snowfall. Verify resort conditions and roads before travel.</p><p>Winter photograph: <a href="https://commons.wikimedia.org/wiki/File:NC_Mountains_in_winter.jpg" rel="noopener noreferrer" target="_blank"><u>ShantellSmith / Wikimedia Commons</u></a>, CC BY-SA 4.0. Forecasts: Open-Meteo. Station records: NOAA GHCN-Daily. Map data: © OpenStreetMap contributors.</p></div><div class="footer-links"><a href="/methodology/">Methodology & sources</a><a href="https://drivenc.gov/" target="_blank" rel="noopener noreferrer">Road conditions ↗</a><a href="https://www.nps.gov/blri/planyourvisit/roadclosures.htm" target="_blank" rel="noopener noreferrer">Parkway closures ↗</a></div></div></footer>`;
 $('menu-button')?.addEventListener('click',()=>{const nav=$('mobile-nav'),expanded=nav.classList.toggle('open');$('menu-button').setAttribute('aria-expanded',String(expanded))});
}
function statusMessage(msg,kind='loading'){$('feed-status').textContent=msg;$('status-dot').className='status-dot '+kind;}
function viewTemplate(){
 if(currentRoute.kind==='home')return `<section class="hero"><div class="hero-glow"></div><div id="snowfall-layer" class="snowfall-layer" aria-hidden="true"></div><div class="container hero-content"><div class="eyebrow" id="storm-eyebrow">NORTH CAROLINA SNOW INTELLIGENCE</div><h1 class="hero-title" id="hero-title">Every mountain.<br><span class="light">Every snow day.</span></h1><p id="hero-copy" class="hero-copy">Discover where snow is falling, what's coming next, and whether it's time to head for the mountains.</p><div class="hero-actions"><a href="#mountain-forecast" class="btn btn-primary">Explore the snow forecast ↓</a><a href="/snowfall/" class="btn btn-ghost">Explore snowfall history ↗</a></div><div class="hero-note">Open-Meteo forecast estimates · <span id="forecast-updated">Fetching the latest run…</span> · <a href="/methodology/">How we calculate totals</a></div></div></section><div class="container"><div class="stat-row" id="top-stats">${Array.from({length:4},()=>'<div class="skeleton"></div>').join('')}</div><section class="section"><div id="storm-banner"></div><div class="section-top" style="margin-top:27px"><div><div class="eyebrow">THE NEXT SEVEN DAYS</div><h2>Where winter is heading</h2><p>Forecast snowfall at representative mountain elevations, not measured on the slopes.</p></div><div id="period-buttons" class="period-control" role="group" aria-label="Snow forecast period"></div></div><div class="columns"><div class="panel forecast-chart"><div class="eyebrow">DAILY SNOWFALL POTENTIAL</div><h3 style="font:700 19px var(--display);margin:10px 0 0">Biggest forecast anywhere in NC</h3><div id="week-chart" class="chart-bars"><div class="empty">Loading daily snow totals…</div></div><div class="mini-source">Each bar is the highest daily model forecast among the tracked mountain points, not a statewide accumulation.</div></div><div class="panel storm-panel" id="storm-watch"><div class="eyebrow">STORM WATCH</div><div class="empty">Checking the seven-day forecast…</div></div></div></section><section class="section-tight" id="mountain-forecast"><div class="section-top"><div><div class="eyebrow">LIVE MODEL OUTLOOK</div><h2>Mountain-by-mountain</h2><p>Five ski mountains and eight high-elevation destinations.</p></div><div id="mountain-filters" class="filters"></div></div><div class="location-grid" id="location-grid">${Array.from({length:6},()=>'<div class="skeleton"></div>').join('')}</div></section><section class="section"><div class="section-top"><div><div class="eyebrow">GEOGRAPHIC OVERVIEW</div><h2>Snow across the mountains</h2><p>Choose any location to explore the latest forecast.</p></div></div><div class="panel map-panel"><div id="snow-map" class="map-canvas"></div></div></section><section class="section-tight"><div class="section-top"><div><div class="eyebrow">THE SKI REPORT</div><h2>Before you buy your lift ticket</h2><p>Operating status from the North Carolina Ski Areas Association, when a recent report can be verified.</p></div><a class="text-link" href="https://www.goskinc.com/snow-reports/" target="_blank" rel="noopener noreferrer">Official association reports ↗</a></div><div class="panel panel-pad" id="resort-reports"><div class="empty">Loading resort reports…</div></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">THE SNOW ARCHIVE</div><h2>How does this winter compare?</h2><p>Explore year-by-year history, monthly snowfall, and actual NOAA station readings—not mixed together.</p></div></div><div class="notice"><span class="notice-icon">◉</span><div><strong>Two different kinds of snow data.</strong> Forecasts and historical model estimates help compare mountain locations. NOAA station measurements describe conditions at specific instruments; they are not readings from resort slopes. <a href="/snowfall/" class="text-link">Open the snowfall explorer ↗</a></div></div></section></div>`;
 if(currentRoute.kind==='mountains')return `<div class="container"><section class="page-head"><div class="eyebrow">ALL NORTH CAROLINA MOUNTAIN POINTS</div><h1>Explore the mountains.</h1><p>Compare all the places that matter for a snow day: ski areas, high peaks, and mountain towns. Forecasts are location-specific estimates at the listed elevation.</p></section><div class="section-top"><div><h2>Forecast comparison</h2><p>Sorted by the next 72 hours of natural snowfall.</p></div><div id="mountain-filters" class="filters"></div></div><div id="location-grid" class="location-grid">${Array.from({length:6},()=>'<div class="skeleton"></div>').join('')}</div><section class="section"><div class="section-top"><div><h2>Map the snow</h2><p>Compare modeled totals geographically, then open any location.</p></div></div><div class="panel map-panel"><div id="snow-map" class="map-canvas"></div></div></section></div>`;
 if(currentRoute.kind==='snowfall')return `<div class="container"><section class="page-head"><div class="eyebrow">HISTORICAL SNOWFALL & OBSERVATIONS</div><h1>The snow archive.</h1><p>Explore modeled snowfall back to 2016 and compare it with NOAA climate-station measurements where available. Every value identifies its origin, location, and coverage.</p></section><div class="notice"><span class="notice-icon">◈</span><div><strong>Not all snow totals mean the same thing.</strong> A resort's season report, a historical model, and a NOAA station measurement are separate datasets. We never silently combine them, and we don't call modeled snowfall “actual.”</div></div><section class="section-tight"><div class="panel panel-pad"><div class="control-row"><div class="form-group" style="min-width:190px;flex:2"><label class="control-label" for="history-place">Mountain / location</label><select class="select" id="history-place">${LOCATIONS.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="form-group" style="flex:1"><label class="control-label" for="history-year">Ending year</label><select class="select" id="history-year">${Array.from({length:yearNow-2016+1},(_,i)=>yearNow-i).map(y=>`<option value="${y}">${y}</option>`).join('')}</select></div><div class="form-group" style="flex:2"><label class="control-label" for="history-station">Independent station</label><select class="select" id="history-station"><option value="auto">Nearest supported station / none</option>${STATIONS.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}<option value="none">Do not show station data</option></select></div></div><div style="margin-top:20px" id="history-mode" class="period-control" role="group" aria-label="Historical period"><button data-mode="winter" aria-pressed="true">Winter season (Oct–Apr)</button><button data-mode="calendar" aria-pressed="false">Calendar year</button></div><div class="mini-source" style="margin-top:14px" id="history-source">Historical model values and station readings will load for the selected location.</div></div></section><section class="section-tight"><div class="section-top"><div><div class="eyebrow">MONTH BY MONTH</div><h2 id="history-title">Snowfall by month</h2><p id="history-intro">Daily amounts aggregated by calendar month, in inches.</p></div></div><div class="panel history-chart" id="history-chart"><div class="empty">Loading historical model and station data…</div></div></section><section class="section-tight"><div class="section-top"><div><div class="eyebrow">SEASON-TO-SEASON</div><h2>How the years stack up</h2><p>Same location, same modeled data source. Incomplete years are labeled, never presented as complete seasons.</p></div></div><div class="panel history-chart" id="year-comparison"><div class="empty">Loading historical comparisons…</div></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">SOURCE VERIFICATION</div><h2>What's actually been measured?</h2></div></div><div class="panel panel-pad" id="station-details"><div class="empty">Station information will appear here.</div></div></section></div>`;
 if(currentRoute.kind==='resort'){const r=currentRoute.resort;return `<div class="resort-hero"><div class="container"><a class="text-link" href="/mountains/">← All mountains</a><div class="eyebrow" style="margin-top:25px">${esc(r.region).toUpperCase()} · SKI RESORT</div><h1>${esc(r.name)}</h1><p>Natural snowfall forecasts at approximately ${Math.round(r.elevation*3.28084).toLocaleString()} ft, resort condition reports, historical snow data, and real mapped ski runs. Everything important for your next trip in one place.</p><div class="hero-actions"><a class="btn btn-primary" href="#weather">See forecast ↓</a><a class="btn" href="#trail-map">Explore ski runs ↓</a><a class="btn btn-ghost" href="${esc(r.report)}" target="_blank" rel="noopener noreferrer">Official conditions ↗</a></div><div id="resort-stat-row" class="resort-stat-row">${Array.from({length:4},()=>'<div class="skeleton"></div>').join('')}</div></div></div><div class="container"><section class="section" id="weather"><div class="section-top"><div><div class="eyebrow">SEVEN-DAY FORECAST</div><h2>When is the snow arriving?</h2><p>Modeled near the ski area summit. Snowfall, rain and temperature vary across the mountain.</p></div></div><div class="panel panel-pad"><div id="resort-week" class="table-scroll"><div class="empty">Loading daily snowfall forecast…</div></div><div class="mini-source" style="margin-top:14px">Snowfall estimates are natural snowfall only, not machine-made snow. Always confirm conditions on the resort's official report.</div></div></section><section class="section-tight"><div class="section-top"><div><div class="eyebrow">SLOPES AND OPERATIONS</div><h2>What's open?</h2><p>Fresh association status when available; live trail and lift counts require the resort's own report.</p></div></div><div class="panel panel-pad" id="resort-conditions"><div class="empty">Checking the latest resort report…</div></div></section><section class="section" id="trail-map"><div class="section-top"><div><div class="eyebrow">EXPLORE THE MOUNTAIN</div><h2>Interactive trail map</h2><p>Real community-mapped piste and lift geometries, color-coded by published difficulty. This is not an operating-status map.</p></div><a class="text-link" href="${esc(r.map)}" target="_blank" rel="noopener noreferrer">Official mountain map ↗</a></div><div class="panel trail-wrap"><div id="resort-trail-map" class="trail-map"></div><div class="trail-overlay-note">Map from OpenStreetMap contributions where available. Incomplete community coverage is possible. Consult the official trail map for navigation or closures.</div></div><div class="map-legend"><span><i class="legend-dot" style="background:#67c8a4"></i>Easy</span><span><i class="legend-dot" style="background:#72bde6"></i>Intermediate</span><span><i class="legend-dot" style="background:#151d30;border:1px solid #94a8b5"></i>Advanced</span><span><i class="legend-dot" style="background:#d7b1d0"></i>Expert</span><span><i class="legend-dot" style="background:#e6c282"></i>Lifts</span></div><div id="trail-inventory" class="panel panel-pad" style="margin-top:14px"><div class="empty">Loading community trail geometry…</div></div></section><section class="section-tight"><div class="section-top"><div><div class="eyebrow">SNOW THIS SEASON</div><h2>Three very different totals</h2><p>Resort reports, modeled snowfall, and measured station snow are not interchangeable.</p></div></div><div id="resort-snow-history" class="comparison-grid">${Array.from({length:3},()=>'<div class="skeleton"></div>').join('')}</div><div style="margin-top:15px"><a class="btn" href="/snowfall/?place=${encodeURIComponent(r.id)}">Explore historical snowfall and years ↗</a></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">BEFORE YOU DRIVE</div><h2>Plan with the right information</h2></div></div><div class="list-links"><a class="btn" href="${esc(r.report)}" target="_blank" rel="noopener noreferrer">Official resort conditions ↗</a><a class="btn" href="${esc(r.webcam)}" target="_blank" rel="noopener noreferrer">Resort cameras & updates ↗</a><a class="btn" href="https://drivenc.gov/" target="_blank" rel="noopener noreferrer">NC road closures ↗</a><a class="btn" href="https://www.nps.gov/blri/planyourvisit/roadclosures.htm" target="_blank" rel="noopener noreferrer">Parkway status ↗</a></div></section></div>`}
 if(currentRoute.kind==='trail-maps')return `<div class="container"><section class="page-head"><div class="eyebrow">SKI TERRAIN · GEOGRAPHIC EXPLORATION</div><h1>Follow every line.</h1><p>Explore real community-mapped trails on interactive terrain maps. Difficulty colors, run labels, lifts and the resort's official trail map are all within reach. We do not draw invented piste routes.</p></section><div class="location-grid">${RESORTS.map(r=>`<a href="/resorts/${r.slug}/#trail-map" class="panel location-card"><div class="location-region">${esc(r.region)}</div><h2 class="location-name">${esc(r.name)}</h2><div class="location-sub">Mapped ski trails and lifts · ${esc(r.town)}, NC</div><div class="location-values"><span class="text-link">Explore trail map</span><span class="loc-arrow">↗</span></div></a>`).join('')}</div><section class="section"><div class="notice"><span class="notice-icon">⌁</span><div><strong>A note about accuracy.</strong> These are actual OpenStreetMap geometries when contributors have mapped them. They are different from the custom artist-drawn maps used on earlier versions of SkiNC, which aren't in the current GitHub repository. Where community mapping is incomplete, we direct you to the resort's official map rather than fabricate a trail.</div></div></section></div>`;
 if(currentRoute.kind==='methodology')return `<div class="container"><section class="page-head"><div class="eyebrow">WEATHER DATA YOU CAN TRUST</div><h1>What the numbers actually mean.</h1><p>Snow forecasts can be wrong. Resort reporting, independent observations, and retrospective weather models are measuring or estimating different things. SkiNC makes those differences explicit.</p></section><div class="section-tight"><div class="panel method-box"><h3>1. Future snowfall forecast — modeled, not observed</h3><p>The forecast comes from <a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener noreferrer">Open-Meteo</a>, sampled at each mountain's approximate summit or geographic elevation. Daily snowfall is measured in model centimeters and converted to inches at 2.54 cm per inch. Three-day and seven-day totals sum daily estimates. Different models, summit exposures, and local terrain can produce different real outcomes.</p><p>Storm totals group adjacent forecast days with meaningful snowfall. We allow one quiet day inside a storm sequence, so a three-day event is not necessarily three consecutive days with accumulation. The winter-wonderland theme appears when a tracked location forecasts at least 3 inches during the next three days, and becomes more dramatic above 6 inches.</p><h3>2. Independent station snowfall — observed at a specific instrument</h3><p>These data are actual <a href="https://www.ncei.noaa.gov/pub/data/ghcn/daily/" target="_blank" rel="noopener noreferrer">NOAA GHCN-Daily</a> reports, not resort slope measurements. We currently support named NOAA stations at Beech Mountain and Mount Mitchell. A station has its own elevation, location, timing and possible missing readings. NOAA SNOW observations are stored in millimeters; the site converts to inches. Quality-flagged and missing days are excluded. Monthly values with missing days are marked incomplete.</p><h3>3. Historic snowfall model — reconstructed, not a station record</h3><p>The <a href="https://open-meteo.com/en/docs/historical-weather-api" target="_blank" rel="noopener noreferrer">Open-Meteo Historical Weather API</a> provides historical modeled/reanalysis snowfall values. These are useful for comparing different locations and years. They do not independently prove snowfall at a summit, on a ski trail, or at a climate station. Recent archive days can lag real time and are not shown as current observed snowfall.</p><h3>4. Resort-reported seasonal snowfall — separate source</h3><p>Resorts may measure snow on specific slopes, at the base, or at other locations; season totals are not standardized across ski areas. SkiNC only displays a numerical resort-reported seasonal total if it can retrieve it with a verifiable source and report time. Otherwise the field is shown as unavailable with a direct link to the resort's official report. Snowmaking is never counted as natural snowfall.</p><h3>5. Resort opening status and trail geometry</h3><p>Association operating status is retrieved from the <a href="https://www.goskinc.com/snow-reports/" target="_blank" rel="noopener noreferrer">North Carolina Ski Areas Association</a>; only reports updated within 48 hours are treated as current. Trail geometry comes from <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> via Overpass. These community records may not cover all runs and do not establish which pistes or lifts are open. Follow official resort postings and signage.</p><h3>6. Travel safety</h3><p>Check <a href="https://drivenc.gov/" target="_blank" rel="noopener noreferrer">DriveNC</a> for road and snow/ice conditions and the <a href="https://www.nps.gov/blri/planyourvisit/roadclosures.htm" target="_blank" rel="noopener noreferrer">Blue Ridge Parkway</a> for closures. Weather conditions can change faster than published reports; SkiNC is decision support, not a travel safety guarantee.</p><p class="mini-source">Attribution: Open-Meteo, NOAA NCEI, NCSAA, OpenStreetMap contributors. Photo: ShantellSmith (CC BY-SA 4.0). SkiNC does not claim affiliation with these organizations.</p></div></div></div>`;
 return `<div class="container"><section class="page-head"><div class="eyebrow">PAGE NOT FOUND</div><h1>Wrong turn on the mountain.</h1><p>That page isn't available. Head back to the snow dashboard.</p><p><a class="btn btn-primary" href="/">Back to SkiNC</a></p></section></div>`;
}

function weatherRows(){return LOCATIONS.map(loc=>({loc,dat:state.byId.get(loc.id)}));}
function weatherPeriod(dat,days=state.period){return dat?sum(dat.days.slice(0,days).map(d=>d.snow)):null}
function updateSnowMode(){const max=Math.max(0,...[...state.byId.values()].map(d=>weatherPeriod(d,3)||0));document.body.classList.toggle('snow-watch',max>=3);document.body.classList.toggle('snowstorm',max>=6);const layer=$('snowfall-layer');if(!layer)return;layer.replaceChildren();if(max<3)return;const count=matchMedia('(prefers-reduced-motion: reduce)').matches?0:(max>=6?68:35);for(let i=0;i<count;i++){const f=document.createElement('span');f.className='flake';f.style.cssText=`left:${(i*47.31)%100}%;animation-delay:-${(i*1.71)%9}s;animation-duration:${5+(i*7)%7}s;opacity:${.3+(i%6)*.11};width:${i%4===0?4:2}px;height:${i%4===0?4:2}px`;layer.append(f)}}
function transformForecast(raw){const byId=new Map();for(const row of raw.items||[]){const f=row.forecast,d=f.daily||{};if(!Array.isArray(d.time)||!Array.isArray(d.snowfall_sum))continue;const unit=f.daily_units?.snowfall_sum||'cm';const factor=/\binch\b|^in$/i.test(unit)?1:1/2.54;const days=d.time.map((date,i)=>({date,snow:typeof d.snowfall_sum[i]==='number'?Math.max(0,d.snowfall_sum[i]*factor):null,high:d.temperature_2m_max?.[i],low:d.temperature_2m_min?.[i],rainMm:d.rain_sum?.[i],wind:d.wind_speed_10m_max?.[i],prob:d.precipitation_probability_max?.[i],code:d.weather_code?.[i]}));if(days.length)byId.set(row.id,{days,current:f.current||{},hourly:f.hourly||{},unit});}return byId}
async function fallbackForecast(){
 const qs=new URLSearchParams({latitude:LOCATIONS.map(x=>x.lat).join(','),longitude:LOCATIONS.map(x=>x.lon).join(','),elevation:LOCATIONS.map(x=>x.elevation).join(','),timezone:'America/New_York',temperature_unit:'fahrenheit',wind_speed_unit:'mph',forecast_days:'7',current:'temperature_2m,weather_code,wind_speed_10m',daily:'snowfall_sum,temperature_2m_max,temperature_2m_min,weather_code,precipitation_probability_max,rain_sum,wind_speed_10m_max'});
 const raw=await requestJSON('https://api.open-meteo.com/v1/forecast?'+qs,22000);const forecasts=Array.isArray(raw)?raw:[raw];return {source:'Open-Meteo (direct)',fetchedAt:new Date().toISOString(),items:forecasts.map((forecast,i)=>({id:LOCATIONS[i]?.id,forecast}))};
}
async function loadForecast(){
 const cached=storage.get('forecast',30*60*1000);
 if(cached){applyForecast(cached,true)}
 try{let v;try{v=await requestJSON('/api/forecast',21000)}catch{v=await fallbackForecast()}if(!v.items?.length)throw Error('No weather locations returned');storage.set('forecast',v);applyForecast(v,false)}
 catch(err){if(!state.forecast){state.loading=false;statusMessage('Forecast unavailable','offline');renderWeatherUnavailable();}else{statusMessage('Using saved forecast','offline')}}
}
function applyForecast(v,cached){state.forecast=v;state.byId=transformForecast(v);state.loading=false;statusMessage((cached?'Saved forecast · ':'Updated · ')+formattedTime(v.fetchedAt),'');updateSnowMode();updatePage();}
function renderWeatherUnavailable(){const message='<div class="notice notice-danger"><span class="notice-icon">!</span><div><strong>Live forecast unavailable.</strong> Weather model data could not be reached. We will not display invented or outdated snowfall totals as current. <button class="btn btn-sm" id="retry-weather" type="button">Retry forecast</button></div></div>';
 for(const id of ['location-grid','resort-week','resort-stat-row'])if($(id))$(id).innerHTML=message;
 if($('top-stats'))$('top-stats').innerHTML='<div class="panel panel-pad" style="grid-column:1/-1">'+message+'</div>';
 if($('retry-weather'))$('retry-weather').addEventListener('click',loadForecast);
}
function updatePage(){if(!state.forecast)return;const kind=currentRoute.kind;if(kind==='home'){renderHome();renderLocations();drawForecastMap()}if(kind==='mountains'){renderLocations();drawForecastMap()}if(kind==='resort'){renderResortWeather()} }
function setPeriodButtons(){const el=$('period-buttons');if(!el)return;el.innerHTML=[1,3,7].map(n=>`<button type="button" data-period="${n}" aria-pressed="${state.period===n}">${n===1?'24 hours':n+' days'}</button>`).join('');el.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.period=+b.dataset.period;renderHome();renderLocations();drawForecastMap()}));}
function renderHome(){const rows=weatherRows().filter(x=>x.dat),max3=rows.length?Math.max(...rows.map(x=>weatherPeriod(x.dat,3))):null;const highest=rows.slice().sort((a,b)=>weatherPeriod(b.dat,3)-weatherPeriod(a.dat,3))[0];const snowCount=rows.filter(x=>weatherPeriod(x.dat,7)>=.1).length;
 const maxSeven=Math.max(0,...rows.map(x=>weatherPeriod(x.dat,7)));
 const isStorm=max3>=3;
 if($('hero-title'))$('hero-title').innerHTML=isStorm?(max3>=6?'A major snow event<br><span class="light">is in the forecast.</span>':'Snow is on<br><span class="light">the horizon.</span>'):'Every mountain.<br><span class="light">Every snow day.</span>';
 if($('hero-copy'))$('hero-copy').textContent=isStorm?`The latest model forecasts up to ${round(max3)} inches over three days at ${highest.loc.name}. Compare the mountains and see the day-by-day breakdown before planning your trip.`:'Your complete North Carolina snowfall and ski conditions dashboard. Find the snow, follow the storms, and choose the best mountain for your next trip.';
 if($('storm-eyebrow'))$('storm-eyebrow').textContent=isStorm?'❄ NORTH CAROLINA STORM WATCH':'NORTH CAROLINA SNOW INTELLIGENCE';
 if($('forecast-updated'))$('forecast-updated').textContent=formattedTime(state.forecast.fetchedAt);
 const statTiles=[['BIGGEST 72-HOUR TOTAL',round(max3)+'″',highest?.loc.name||'No data'],['BIGGEST 7-DAY TOTAL',round(maxSeven)+'″','At one forecast location'],['LOCATIONS WITH SNOW',snowCount+' / '+rows.length,'7-day model outlook'],['FORECAST SOURCE','Open-Meteo','Daily model estimates']];
 if($('top-stats'))$('top-stats').innerHTML=statTiles.map(([name,num,foot])=>`<div class="stat-tile"><div class="stat-label">${esc(name)}</div><div class="stat-num">${esc(num)}</div><div class="stat-foot">${esc(foot)}</div></div>`).join('');
 const banner=$('storm-banner');if(banner)banner.innerHTML=isStorm?`<div class="notice"><span class="notice-icon">❄</span><div><strong>Snow watch active.</strong> ${esc(highest.loc.name)} is forecast up to ${round(max3)}″ of natural snowfall in the next three days. This is a modeled estimate, not a guaranteed accumulation. <a href="/mountains/" class="text-link">Compare mountain totals ↗</a></div></div>`:'';
 setPeriodButtons();renderSevenDayChart(rows);renderStorms(rows);
}
function renderSevenDayChart(rows){const el=$('week-chart');if(!el)return;const first=rows.find(x=>x.dat?.days.length)?.dat.days||[];
 const maxByDay=first.map((d,i)=>{const vals=rows.map(x=>({loc:x.loc,v:x.dat?.days[i]?.snow||0})).sort((a,b)=>b.v-a.v);return {date:d.date,value:vals[0]?.v||0,loc:vals[0]?.loc}});
 const biggest=Math.max(.2,...maxByDay.map(x=>x.value));el.innerHTML=maxByDay.map(x=>`<div class="forecast-col" title="${esc(x.loc?.name||'Mountain')}: ${round(x.value)} inches"><span class="forecast-val">${round(x.value)}″</span><div class="forecast-bar-box"><div class="forecast-bar" style="height:${Math.max(3,x.value/biggest*107)}px"></div></div><span class="forecast-label">${formattedDay(x.date)}</span><span class="forecast-date">${shortDay(x.date)}</span></div>`).join('');}
function stormGroups(rows){if(!rows.length)return[];const first=rows[0].dat.days;const maxes=first.map((day,i)=>({date:day.date,max:Math.max(0,...rows.map(x=>x.dat.days[i]?.snow||0))}));const groups=[];let active=null;
 for(let i=0;i<maxes.length;i++){
  if(maxes[i].max>=.1){if(!active)active={start:i,end:i};else active.end=i}
  else if(active&&i-active.end>1){groups.push(active);active=null}
 }
 if(active)groups.push(active);
 return groups.map(g=>{const points=rows.map(x=>({loc:x.loc,total:sum(x.dat.days.slice(g.start,g.end+1).map(d=>d.snow))})).sort((a,b)=>b.total-a.total);return {...g,points,top:points[0],startDate:maxes[g.start].date,endDate:maxes[g.end].date}}).sort((a,b)=>b.top.total-a.top.total);
}
function renderStorms(rows){const el=$('storm-watch');if(!el)return;const storms=stormGroups(rows);
 if(!storms.length){el.innerHTML=`<div class="eyebrow">STORM WATCH</div><div class="storm-num">All clear</div><p class="storm-description">No significant natural snowfall currently appears in the seven-day outlook for our tracked mountain locations. Forecasts can change quickly.</p><a class="text-link" href="/mountains/">See all mountain outlooks ↗</a>`;return}
 const s=storms[0],days=s.start===s.end?shortDay(s.startDate):shortDay(s.startDate)+' – '+shortDay(s.endDate);
 el.innerHTML=`<div class="eyebrow">LARGEST FORECAST STORM</div><div class="storm-num">${round(s.top.total)}<span style="font-size:22px">″</span></div><div class="storm-dates">${esc(days)} · ${esc(s.top.loc.name)}</div><p class="storm-description">Highest modeled storm total among tracked locations during this event. ${storms.length>1?`${storms.length} potential snowy periods appear in the next 7 days.`:'One potential snowy period appears in the next 7 days.'} Check each mountain's daily forecast before you go.</p><a class="text-link" href="/mountains/">Compare all mountains ↗</a>`;
}
function filterButtons(){const el=$('mountain-filters');if(!el)return;el.innerHTML=[['all','All locations'],['resort','Ski resorts'],['peak','High peaks & towns']].map(([v,label])=>`<button class="filter-button" data-filter="${v}" aria-pressed="${state.filter===v}">${label}</button>`).join('');el.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;renderLocations();drawForecastMap()}));}
function renderLocations(){const el=$('location-grid');if(!el)return;filterButtons();let rows=weatherRows().filter(({loc})=>state.filter==='all'||loc.type===state.filter).sort((a,b)=>(weatherPeriod(b.dat)||-1)-(weatherPeriod(a.dat)||-1));
 el.innerHTML=rows.map(({loc,dat})=>{const href=loc.type==='resort'?`/resorts/${loc.slug}/`:`/snowfall/?place=${loc.id}`;const total=weatherPeriod(dat);const d=dat?.days[0];return `<a class="panel location-card" href="${href}" aria-label="${esc(loc.name)}, ${total===null?'forecast unavailable':round(total)+' inches forecast'}"><div class="location-region">${esc(loc.region)} · ${loc.type==='resort'?'Ski mountain':'Mountain / town'}</div><h3 class="location-name">${esc(loc.name)}</h3><div class="location-sub">${esc(loc.town)} · ${Math.round(loc.elevation*3.28084).toLocaleString()} ft model point</div><div class="location-values"><div><div class="snow-number">${total===null?'—':round(total)}<small> in</small></div><div class="label-under">Next ${state.period===1?'24h':state.period+' days'} · model forecast</div></div><div style="text-align:right"><div style="font-size:13px;color:#d3e4ef;font-weight:750">${d?.low!=null?Math.round(d.low)+'°F low':'—'}</div><div class="label-under">Today</div><div class="loc-arrow" aria-hidden="true">↗</div></div></div></a>`}).join('');}
function clearMaps(){for(const m of state.maps){try{m.remove()}catch{}}state.maps=[]}
function createMap(id,coords,zoom){const el=$(id);if(!el)return null;if(!window.L){el.innerHTML='<div class="map-fallback"><strong>Interactive map service unavailable</strong><span>Use the mountain cards or official trail map links. Geographic forecasts are still available.</span></div>';return null}try{const m=L.map(id,{scrollWheelZoom:false,zoomControl:true}).setView(coords,zoom);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank">OpenStreetMap</a> contributors',maxZoom:18}).addTo(m);state.maps.push(m);return m}catch(e){return null}}
function drawForecastMap(){if(!$('snow-map')||!state.byId.size)return;clearMaps();$('snow-map').replaceChildren();const m=createMap('snow-map',[35.82,-82.65],8);if(!m)return;const bounds=[];for(const {loc,dat} of weatherRows()){
 if(state.filter!=='all'&&loc.type!==state.filter)continue;const amount=weatherPeriod(dat),text=amount===null?'—':round(amount)+'″';const html=`<div class="map-marker ${amount>=.1?'snowing':''} ${loc.type==='peak'?'mountain':''}">${esc(loc.name.split(' ')[0])} ${text}</div>`;
 const pin=L.divIcon({html,className:'',iconSize:[120,32],iconAnchor:[60,15]});const marker=L.marker([loc.lat,loc.lon],{icon:pin}).addTo(m);const url=loc.type==='resort'?`/resorts/${loc.slug}/`:`/snowfall/?place=${loc.id}`;marker.bindPopup(`<strong>${esc(loc.name)}</strong><p>${amount===null?'Forecast unavailable':round(amount)+' inches forecast in '+state.period+' day(s)'}</p><a href="${url}">Explore location ↗</a>`);bounds.push([loc.lat,loc.lon]);}
 if(bounds.length>1)m.fitBounds(bounds,{padding:[36,55],maxZoom:9});setTimeout(()=>m.invalidateSize(),80);
}
async function loadListings(){try{const data=await requestJSON('/api/listings',17000);state.listings=data.listings||{};renderReports();if(currentRoute.kind==='resort')renderResortHistory().catch(()=>{})}catch{state.listings={};renderReports()}}
async function loadReports(){try{const data=await requestJSON('/api/resorts',16000);state.reports=data.reports||{};renderReports()}catch(e){state.reports={};renderReports()}}
function reportFor(r){return state.reports?.[r.id]||null}
function renderReports(){const el=$('resort-reports');if(el){el.innerHTML=RESORTS.map(r=>{const info=reportFor(r);const fresh=info&&info.status;const listing=state.listings?.[r.id];return `<div class="report-card"><div><div class="report-title"><a href="/resorts/${r.slug}/">${esc(r.name)} ↗</a></div><div class="report-detail">${info?`Association report: ${esc(info.updatedLabel)}${info.stale?' · not current':''}`:'No verified association update available'}${listing?' · SkiSoutheast season listing: '+esc(listing.seasonSnow)+'″':''} · <a class="text-link" href="${esc(r.report)}" target="_blank" rel="noopener noreferrer">Official mountain report ↗</a></div></div><div class="report-status ${fresh?'status-'+fresh:''}">${fresh?(fresh==='open'?'● Open':'● Closed'):'Not verified'}</div></div>`}).join('')+`<p class="mini-source">Operating status is used only from recent dated association reports. This is not a live lift-count feed.</p>`}
 if(currentRoute.kind==='resort')renderResortConditions();}
function renderResortWeather(){const r=currentRoute.resort,d=state.byId.get(r.id);if(!d)return;
 const temps=d.days[0],st=reportFor(r);const stats=[['NEXT 24 HOURS',round(weatherPeriod(d,1))+'″','Natural snowfall model'],['NEXT 72 HOURS',round(weatherPeriod(d,3))+'″','Natural snowfall model'],['NEXT 7 DAYS',round(weatherPeriod(d,7))+'″','Natural snowfall model'],['TODAY',whole(temps?.low)+'° / '+whole(temps?.high)+'°F','Summit model low / high']];
 if($('resort-stat-row'))$('resort-stat-row').innerHTML=stats.map(([label,num,foot])=>`<div class="resort-stat"><span>${esc(label)}</span><b>${esc(num)}</b><span>${esc(foot)}</span></div>`).join('');
 const week=$('resort-week');if(week)week.innerHTML=`<table class="data-table"><thead><tr><th>Day</th><th>Forecast snow</th><th>Low / high</th><th>Rain</th><th>Wind peak</th><th>Precip. chance</th></tr></thead><tbody>${d.days.map(x=>`<tr><td><strong>${formattedDay(x.date)}</strong><br><span class="mini-source">${shortDay(x.date)}</span></td><td><strong style="color:#bbecff">${round(x.snow)}″</strong></td><td>${whole(x.low)}° / ${whole(x.high)}°F</td><td>${Number.isFinite(x.rainMm)?round(x.rainMm/25.4)+'″':'—'}</td><td>${whole(x.wind)} mph</td><td>${whole(x.prob)}%</td></tr>`).join('')}</tbody></table>`;
 renderResortConditions();
}
function renderResortConditions(){const el=$('resort-conditions');if(!el||currentRoute.kind!=='resort')return;const r=currentRoute.resort,report=reportFor(r);let info='No sufficiently recent operating-status report is available. Check the resort directly.';
 if(report?.status){info=`The NC Ski Areas Association lists this resort as <strong class="${report.status==='open'?'status-open':'status-closed'}">${esc(report.status.toUpperCase())}</strong>. Report last updated ${esc(report.updatedLabel)}. ${report.snowmaking?'Snowmaking: '+esc(report.snowmaking)+'.':''}`}
 else if(report?.stale){info=`The association's most recent identified entry is dated ${esc(report.updatedLabel)}, which is too old to treat as today's operating status.`}
 el.innerHTML=`<div class="notice"><span class="notice-icon">◉</span><div>${info}</div></div><div class="report-card"><div><div class="report-title">Trail and lift counts</div><div class="report-detail">Check the official source for current operations, terrain parks and grooming. Counts have not been independently verified by SkiNC.</div></div><a class="btn btn-sm" target="_blank" rel="noopener noreferrer" href="${esc(r.report)}">Check trail status ↗</a></div><div class="report-card"><div><div class="report-title">Natural snow versus snowmaking</div><div class="report-detail">Forecast values shown elsewhere are natural snowfall estimates. Artificial snowmaking must not be added to that total.</div></div><a class="text-link" href="/methodology/">Methods ↗</a></div>`;
}

function difficultyColor(d){return ({novice:'#67c8a4',easy:'#67c8a4',intermediate:'#72bde6',advanced:'#202d3e',expert:'#d7b1d0',freeride:'#dfc6a7'}[d]||'#b0c5d0')}
async function loadTrails(){if(currentRoute.kind!=='resort')return;const r=currentRoute.resort;const el=$('resort-trail-map');if(!el)return;
 let data;try{data=storage.get('trails-'+r.id,24*3600000)||await requestJSON('/api/trails?resort='+r.id,26000);storage.set('trails-'+r.id,data)}catch(e){data={features:[]}}
 const features=(data.features||[]).filter(f=>Array.isArray(f.coords)&&f.coords.length>=2);
 const map=createMap('resort-trail-map',[r.lat,r.lon],14);
 if(map&&features.length){const bounds=[];for(const f of features){const points=f.coords;const color=f.kind==='lift'?'#e6c282':difficultyColor(f.difficulty);const p=L.polyline(points,{color:'#071c2f',weight:f.kind==='lift'?5:9,opacity:.75}).addTo(map);const l=L.polyline(points,{color,weight:f.kind==='lift'?3.4:5.8,opacity:.95,dashArray:f.kind==='lift'?'5 8':null}).addTo(map);if(f.name){l.bindTooltip(esc(f.name),{className:'trail-tooltip',permanent:true,direction:'center',opacity:.82})}bounds.push(...points);}
 map.fitBounds(bounds,{padding:[35,35],maxZoom:15});}
 else if(map){L.marker([r.lat,r.lon]).addTo(map).bindPopup(esc(r.name));}
 const list=$('trail-inventory');if(list){const trails=features.filter(f=>f.kind==='run'),lifts=features.filter(f=>f.kind==='lift');list.innerHTML=`<div class="eyebrow">COMMUNITY MAPPING COVERAGE</div><h3 style="font:700 21px var(--display);margin:10px 0">${trails.length} mapped piste segments · ${lifts.length} lift lines</h3>${features.length?`<p class="mini-source">These are OpenStreetMap way segments, not a guaranteed count of distinct named ski runs or operating lifts.</p><div class="trail-list">${trails.filter(f=>f.name).sort((a,b)=>a.name.localeCompare(b.name)).map(f=>`<span class="trail-name"><i class="trail-bullet" style="background:${difficultyColor(f.difficulty)}"></i>${esc(f.name)}</span>`).join('')}</div>`:`<div class="notice notice-warning"><div><strong>Trail geometry couldn't be verified.</strong> This interactive map is centered on the resort, but no reliable route segments were retrieved. Use the <a href="${esc(r.map)}" class="text-link" target="_blank" rel="noopener noreferrer">official trail map ↗</a> rather than relying on made-up trails.</div></div>`}`;}
}
function monthsMap(months){return new Map((months||[]).map(x=>[x.month,x]))}
function periodsFor(year,mode){if(mode==='calendar')return Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`);return [10,11,12].map(n=>`${year-1}-${n}`).concat([1,2,3,4].map(n=>`${year}-${String(n).padStart(2,'0')}`))}
const monthName=key=>new Date(key+'-15T12:00:00').toLocaleDateString('en-US',{month:'short',timeZone:'America/New_York'});
function getPeriodValues(year,mode,model,observed){const keys=periodsFor(year,mode);const modeled=keys.map(k=>model.get(k)||null);const measured=keys.map(k=>observed.get(k)||null);return {keys,modeled,measured};}
function stationSelected(){return state.historyStation==='none'?null:state.historyStation==='auto'?(getLocation(state.historyPlace)?.station||null):state.historyStation;}
async function loadStation(id){if(!id)return null;if(state.observations[id])return state.observations[id];let d=storage.get('obs-'+id,12*3600000);if(!d){try{d=await requestJSON('/api/observations?station='+id,22000);storage.set('obs-'+id,d)}catch{d={station:getStation(id),error:'NOAA data unavailable',months:[]}}}state.observations[id]=d;return d}
async function loadHistory(place){const target=getLocation(place);if(!target)return;state.historyPlace=target.id;state.history=null;renderHistory();let d=storage.get('history-'+target.id,24*3600000);
 if(!d){try{d=await requestJSON('/api/history?place='+target.id,28000);storage.set('history-'+target.id,d)}catch{d={error:'Historical archive is currently unavailable',months:[],place:target.id}}}
 if(state.historyPlace!==target.id)return;
 state.history=d;await loadStation(stationSelected());if(state.historyPlace===target.id)renderHistory();
}
function updateHistoryControls(){if($('history-place'))$('history-place').value=state.historyPlace;if($('history-year'))$('history-year').value=String(state.historyYear);if($('history-station'))$('history-station').value=state.historyStation;
 $('history-mode')?.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.historyMode)));
}
function bindHistory(){const qp=new URLSearchParams(location.search);const place=qp.get('place');if(getLocation(place))state.historyPlace=place;
 updateHistoryControls();$('history-place')?.addEventListener('change',e=>{state.historyPlace=e.target.value;state.historyStation='auto';history.replaceState(null,'','/snowfall/?place='+encodeURIComponent(state.historyPlace));updateHistoryControls();loadHistory(state.historyPlace)});
 $('history-year')?.addEventListener('change',e=>{state.historyYear=+e.target.value;renderHistory()});
 $('history-station')?.addEventListener('change',async e=>{state.historyStation=e.target.value;renderHistory();await loadStation(stationSelected());renderHistory()});
 $('history-mode')?.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.historyMode=b.dataset.mode;updateHistoryControls();renderHistory()}));
 loadHistory(state.historyPlace);
}
function renderHistory(){if(currentRoute.kind!=='snowfall')return;updateHistoryControls();const d=state.history;if(!d){$('history-chart').innerHTML='<div class="empty">Loading Open-Meteo historical archive and NOAA measurements…</div>';return}
 const site=getLocation(state.historyPlace),sid=stationSelected(),station=sid?getStation(sid):null,obs=sid?state.observations[sid]:null,model=monthsMap(d.months),measured=monthsMap(obs?.months),year=state.historyYear,mode=state.historyMode,{keys,modeled,measured:measures}=getPeriodValues(year,mode,model,measured);
 const title=mode==='winter'?`Winter ${year-1}–${String(year).slice(2)}`:`Calendar year ${year}`;
 $('history-title').textContent=title+' · monthly snowfall';$('history-intro').textContent='Blue = historical modeled snowfall. Green = independent NOAA station reading, when a complete month is available.';
 $('history-source').textContent=`Selected forecast point: ${site.name} (${Math.round(site.elevation*3.28084)} ft). Historical source: Open-Meteo reanalysis, through ${d.availableThrough||'unavailable'}. ${station?'Observed station: '+station.name+'.':'No station assigned to this location.'}`;
 const max=Math.max(1,...modeled.map(m=>m?.totalIn||0),...measures.map(m=>m?.snowfallIn||0));
 const rows=keys.map((key,i)=>{const m=modeled[i],o=measures[i];const modelValue=m&&m.available===m.days?m.totalIn:null;const obsValue=o?.complete?o.snowfallIn:null;
  return `<div class="history-row"><div class="history-label">${monthName(key)}<div class="mini-source">${key.slice(0,4)}</div></div><div><div class="history-track" title="Historical model: ${modelValue===null?'unavailable':round(modelValue)+' inches'}"><div class="history-fill" style="width:${modelValue===null?0:modelValue/max*100}%"></div></div>${station?`<div class="history-track" style="margin-top:4px" title="NOAA station ${obsValue===null?'incomplete or unavailable':round(obsValue)+' inches'}"><div class="history-fill measured" style="width:${obsValue===null?0:obsValue/max*100}%"></div></div>`:''}</div><div class="history-value">${modelValue===null?'—':round(modelValue)+'″'}${station?`<div style="color:#9ce0c8;font-size:11px;margin-top:3px">${obsValue===null?'—':round(obsValue)+'″'}</div>`:''}</div></div>`;
 }).join('');
 const modelFull=modeled.every(m=>m&&m.available===m.days);const totalModel=modelFull?sum(modeled.map(m=>m.totalIn)):null;
 const obsFull=station&&measures.every(m=>m?.complete),totalObs=obsFull?sum(measures.map(m=>m.snowfallIn)):null;
 $('history-chart').innerHTML=`<div class="comparison-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:15px"><div class="panel comparison-card"><div class="stat-label">HISTORICAL MODEL ${mode==='winter'?'WINTER':'YEAR'} TOTAL</div><div class="num">${totalModel===null?'Incomplete':round(totalModel)+'″'}</div><p>Open-Meteo reanalysis at ${esc(site.name)}, ${Math.round(site.elevation*3.28084)} ft</p></div><div class="panel comparison-card"><div class="stat-label">INDEPENDENT STATION TOTAL</div><div class="num">${totalObs!==null?round(totalObs)+'″':'Unavailable / incomplete'}</div><p>${station?esc(station.name)+' · '+Math.round(station.elevation*3.28084)+' ft':'No nearby station configured'}. Complete daily records required.</p></div></div>${rows}<div class="history-legend"><span><i class="swatch"></i>Historical model</span>${station?'<span><i class="swatch measured"></i>NOAA station observed</span>':''}<span>— = missing / incomplete</span></div>`;
 const years=Array.from({length:Math.min(10,yearNow-2016+1)},(_,i)=>yearNow-i).filter(y=>y>=2017||mode==='calendar');const annual=years.map(y=>{const p=periodsFor(y,mode),mr=p.map(k=>model.get(k));const complete=mr.every(x=>x&&x.available===x.days);return {year:y,total:complete?sum(mr.map(x=>x.totalIn)):null}});const maxAnnual=Math.max(1,...annual.map(x=>x.total||0));
 $('year-comparison').innerHTML=annual.map(x=>`<div class="history-row"><div class="history-label">${x.year}</div><div class="history-track"><div class="history-fill" style="width:${x.total===null?0:x.total/maxAnnual*100}%"></div></div><div class="history-value">${x.total===null?'—':round(x.total)+'″'}</div></div>`).join('')+`<div class="mini-source" style="margin-top:15px">${mode==='winter'?'Winter seasons are October through April, labeled by ending year.':'Calendar years are January through December.'} Incomplete periods are excluded from totals; the current year will normally be incomplete. Model-derived values are not measurements.</div>`;
 $('station-details').innerHTML=station?`<h3 style="font:700 20px var(--display);margin:0 0 12px">${esc(station.name)}</h3><span class="tag tag-measured">OBSERVED · NOAA GHCN-DAILY</span><p style="font-size:13px;color:#b3cbdd;line-height:1.8">Station elevation: ${Math.round(station.elevation*3.28084).toLocaleString()} ft. ${esc(station.name)} is a particular monitoring site, not a sensor installed on ${esc(site.name)}. Snowfall can be dramatically different on adjacent slopes and at different elevations. Only complete monthly records are plotted as comparable totals.</p>${obs?.error?`<p class="notice notice-warning">${esc(obs.error)}</p>`:''}<a class="btn btn-sm" href="${esc(station.url)}" target="_blank" rel="noopener noreferrer">View NOAA station metadata ↗</a>`:`<h3 style="font:700 20px var(--display)">No matched independent station yet</h3><p style="font-size:13px;color:#b3cbdd">We won't pair a distant instrument with this location and call its reading local snowfall. You can select Beech Mountain or Mount Mitchell manually to explore those genuine measured records, but that comparison is geographical context only.</p>`;
}
async function renderResortHistory(){if(currentRoute.kind!=='resort')return;const r=currentRoute.resort,el=$('resort-snow-history');if(!el)return;
 const data=storage.get('history-'+r.id,24*3600000)||await requestJSON('/api/history?place='+r.id,27000).catch(()=>null);if(data)storage.set('history-'+r.id,data);
 const stationData=r.station?await loadStation(r.station):null;
 // Winter season-to-date begins October 1. The archive typically trails real time by several days.
 const seasonStart=yearNow+'-10';const seasonMonths=[10,11,12].map(m=>`${yearNow}-${m}`);if(new Date().getMonth()<9){seasonMonths.splice(0,seasonMonths.length,...[10,11,12].map(m=>`${yearNow-1}-${m}`),...[1,2,3,4].map(m=>`${yearNow}-${String(m).padStart(2,'0')}`));}
 const presentMonth=(new Date()).toISOString().slice(0,7);const historicalMonths=data?.months?.filter(m=>seasonMonths.includes(m.month)&&m.month<=presentMonth)||[];
 const modeledTotal=historicalMonths.length?sum(historicalMonths.map(x=>x.totalIn)):null;const observedMonths=stationData?.months?.filter(m=>seasonMonths.includes(m.month)&&m.month<=presentMonth)||[];
 const obsComplete=observedMonths?.length>=historicalMonths.length&&observedMonths?.every(x=>x.complete);const obsTotal=obsComplete&&observedMonths.length?sum(observedMonths.map(x=>x.snowfallIn)):null;
 const listing=state.listings?.[r.id];const cards=[['PUBLISHED SEASON SNOW',listing?listing.seasonSnow+(listing.trace?'':'″'):'Not verified',listing?'Listed by SkiSoutheast, a third-party aggregator; not independently verified or equivalent to a resort sensor or NOAA station. Check the resort for official figures.':'No dated, verified resort-issued season total available. Check the resort for its most recent report.','unverified'],['HISTORICAL MODEL TO DATE',modeledTotal===null?'Unavailable':round(modeledTotal)+'″',`Open-Meteo modeled/reanalysis snowfall near summit, through ${data?.availableThrough||'unknown date'}. Not a measured total.`,'model'],['NOAA STATION OBSERVED',obsTotal===null?'Incomplete / n/a':round(obsTotal)+'″',r.station?`${esc(getStation(r.station).name)}. Measured at the station, not at the resort. Partial months are not promoted to season totals.`:'No representative nearby station configured.','measured']];
 el.innerHTML=cards.map(([label,num,foot,kind])=>`<div class="panel comparison-card"><div class="stat-label">${label}</div><div class="num">${esc(num)}</div><span class="tag tag-${kind}">${kind==='model'?'REANALYSIS':kind==='measured'?'STATION DATA':'UNVERIFIED'}</span><p>${foot}</p></div>`).join('');
}

function run(){shell(viewTemplate());if(currentRoute.kind==='snowfall'){statusMessage('Snow archive','');bindHistory();return}if(currentRoute.kind==='methodology'||currentRoute.kind==='not-found'||currentRoute.kind==='trail-maps'){statusMessage('About SkiNC','');return}if(currentRoute.kind==='resort'){loadTrails();renderResortHistory().catch(()=>{if($('resort-snow-history'))$('resort-snow-history').innerHTML='<div class="empty">Historical snow sources are temporarily unavailable.</div>'})}
 loadForecast();if(currentRoute.kind==='home'||currentRoute.kind==='resort'){loadReports();loadListings()}}
run();
